#!/bin/zsh
cd "$(dirname "$0")"
D="$(pwd)/gen"
REF="$(pwd)/ref-style.png"
S="ESTILO OBLIGATORIO: exactamente el MISMO estilo de pixel art que los personajes de la imagen adjunta (pixel art de Pokémon Esmeralda / Rojo Fuego de Game Boy Advance: píxeles grandes y nítidos bien visibles, contorno oscuro de 1 píxel, sombreado por bloques con pocas tonalidades, colores muy vivos y alegres). Vista desde arriba en 3/4 como los pueblos de Pokémon. NO dibujes los personajes de la referencia, solo úsala para copiar el estilo. SIN texto, SIN letras, SIN números, SIN marcas de agua."
KEY="El FONDO debe ser magenta puro liso (#FF00FF) en toda la imagen, sin degradado, sin sombras en el fondo; cada objeto bien separado con mucho espacio magenta alrededor. No uses magenta dentro de los dibujos."
DOOR="Cada edificio con la puerta EXACTAMENTE al centro abajo, visto de frente como en Pokémon."
run(){ name=$1; shift; (codex exec -i "$REF" --dangerously-bypass-approvals-and-sandbox --skip-git-repo-check "Usa tu herramienta de generación de imágenes. $* Al final imprime NOMBRE => RUTA COMPLETA de cada imagen generada (aunque no hayas podido copiarla)." < /dev/null > log23-$name.txt 2>&1; echo "DONE $name $?") & }
run bA "$S $KEY $DOOR Crea g-bld-a.png (imagen ancha 16:9) en $D/ con EXACTAMENTE 2 edificios en UNA fila, bien separados: 1) PASTELERÍA grande y muy linda de paredes crema con techo rosa, toldo de rayas rosa y blanco, vitrinas con pasteles y un pastel gigante con fresa decorando el techo; 2) GRANERO rojo grande de granja con techo gris y un silo cilíndrico rojo a un lado, puerta de granero blanca en X."
run bB "$S $KEY $DOOR Crea g-bld-b.png (imagen ancha 16:9) en $D/ con EXACTAMENTE 2 edificios en UNA fila, bien separados: 1) MOLINO de piedra clara con aspas de madera y techo de paja; 2) FRUTERÍA de madera con toldo verde y blanco y cajas de fresas y manzanas al frente."
run bC "$S $KEY $DOOR Crea g-bld-c.png (imagen ancha 16:9) en $D/ con EXACTAMENTE 2 edificios en UNA fila, bien separados: 1) CHOCOLATERÍA de paredes cafés con techo que parece barra de chocolate y toldo café con crema; 2) TIENDA DE ABARROTES de techo azul con toldo azul y blanco y costales de harina al frente."
run bD "$S $KEY $DOOR Crea g-bld-d.png (imagen ancha 16:9) en $D/ con EXACTAMENTE 2 edificios en UNA fila, bien separados: 1) BOUTIQUE de ropa elegante de paredes rosa pastel con techo azul cielo y un vestido en el aparador; 2) MUEBLERÍA de madera con techo verde y un sofá y una lámpara en el aparador."
run h1 "$S $KEY $DOOR Crea g-homes-a.png (imagen ancha 16:9) en $D/ con EXACTAMENTE 2 casas en UNA fila, bien separadas, de color crema con techo de teja ROSA, cortinas rosas y jardineras con flores, con un gatito negro y uno blanco con manchas cafés asomados por las ventanas: 1) CASITA pequeña de dos aguas con chimenea y buzón rosa; 2) CASA MEDIANA más ancha con porche de madera blanca con barandal."
run h2 "$S $KEY $DOOR Crea g-homes-b.png (imagen ancha 16:9) en $D/ con EXACTAMENTE 2 casas en UNA fila, bien separadas, de color crema con techos de teja ROSA, cortinas rosas, flores, con un gatito negro y uno blanco con manchas cafés asomados: 1) CASA GRANDE de dos pisos con una torrecita redonda de techo cónico, balcón con flores y cerca blanca; 2) MANSIÓN muy ancha con dos torrecitas, cúpula con corazón, porche con columnas, fuente pequeña y jardín con cerca blanca."
run h3 "$S $KEY $DOOR Crea g-houses.png (imagen ancha 16:9) en $D/ con EXACTAMENTE 4 casas de vecinos en UNA fila, bien separadas, mismo tamaño: 1) techo AZUL paredes blancas, 2) techo ROJO paredes crema, 3) techo VERDE paredes amarillo pastel, 4) techo MORADO paredes rosa pastel; con ventanas y macetas con flores."
run n1 "$S $KEY Crea g-nature.png (imagen ancha 16:9) en $D/ con EXACTAMENTE 8 objetos en 2 filas de 4, mismo tamaño: 1) árbol frondoso verde redondo, 2) pino verde oscuro, 3) árbol de cerezo grande rosa, 4) árbol de cerezo chico, 5) naranjo con naranjas, 6) seto verde redondo, 7) arbusto con flores rosas, 8) palmera en maceta."
run n2 "$S $KEY Crea g-farm.png (imagen ancha 16:9) en $D/ con EXACTAMENTE 8 objetos en 2 filas de 4, mismo tamaño: 1) gallina blanca de cresta roja, 2) gallina blanca echada en un nido de paja, 3) vaca blanca con manchas negras, 4) arbusto de fresas lleno de fresas rojas, 5) el MISMO arbusto de fresas sin fresas, 6) el MISMO arbusto de fresas con flores blancas, 7) manzano lleno de manzanas rojas, 8) el MISMO manzano sin manzanas."
run p1 "$S $KEY Crea g-props-a.png (imagen ancha 16:9) en $D/ con EXACTAMENTE 8 objetos en 2 filas de 4, mismo tamaño: 1) fuente grande de piedra de tres niveles con agua azul, 2) fuente pequeña de piedra, 3) banca de parque de madera con patas de hierro, 4) farol negro de calle, 5) tramo de cerca de madera café (horizontal, 2 postes), 6) buzón rojo sobre poste de madera, 7) mesa con mantel rojo (mesa del jurado), 8) puesto de globos de colores con toldo azul."
run p2 "$S $KEY Crea g-props-b.png (imagen ancha 16:9) en $D/ con EXACTAMENTE 2 objetos en UNA fila, bien separados: 1) camioncito de comida rosa pastel vendedor de pasteles con un cupcake gigante en el techo, visto de lado; 2) macizo de flores de colores (rojas, amarillas, moradas) con borde de piedritas."
wait
echo ALLDONE
